inputs = ['ijkk', 'wbzca', 'kfbvfw', 'yfkh', 'vxwk']
outputs = ['iyuga', 'wbzca', 'gafbvfw', 'yfgah', 'vhwga']

print("Character-by-character analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"\n{i}: '{inp}' -> '{outp}'")
    print("  Pos: ", end="")
    for j in range(max(len(inp), len(outp))):
        if j < len(inp) and j < len(outp):
            print(f"{j:2}", end=" ")
        elif j < len(inp):
            print(f"{j:2}", end=" ")
        else:
            print("  ", end=" ")
    print()

    print("  Inp: ", end="")
    for j in range(max(len(inp), len(outp))):
        if j < len(inp):
            print(f"'{inp[j]}' ", end=" ")
        else:
            print("   ", end=" ")
    print()

    print("  Out: ", end="")
    for j in range(max(len(inp), len(outp))):
        if j < len(outp):
            print(f"'{outp[j]}' ", end=" ")
        else:
            print("   ", end=" ")
    print()

print("\nLooking for patterns...")
print("Looking at the actual differences:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        print(f"Change {i}: '{inp}' -> '{outp}'")
        # Find where they differ
        min_len = min(len(inp), len(outp))
        for j in range(min_len):
            if inp[j] != outp[j]:
                print(f"  Position {j}: '{inp[j]}' -> '{outp[j]}'")
        if len(inp) != len(outp):
            print(f"  Length change: {len(inp)} -> {len(outp)}")

